// Consolida las 5 noticias en un solo texto y arrastra el edicion_id.
const noticias = $input.all();

// Ordenar por 'orden' para mantener consistencia.
const ordenadas = noticias
  .map((n) => n.json)
  .sort((a, b) => (a.orden ?? 0) - (b.orden ?? 0));

// Armar un texto legible con título + cuerpo de cada noticia.
const textoNoticias = ordenadas
  .map((n, i) => `${i + 1}. ${n.titulo}\n${n.cuerpo}`)
  .join("\n\n");

// El edicion_id (todas las noticias son de la misma edición).
const edicionId = ordenadas[0]?.edicion_id ?? "";

return [
  {
    json: {
      edicion_id: edicionId,
      texto_noticias: textoNoticias,
    },
  },
];

