// Arma el menú de estilos (id + nombre + descripción) para que Groq elija,
// y recupera el texto de las noticias del Code anterior.
const estilos = $input.all().map((e) => e.json);

const menuEstilos = estilos
  .map(
    (e) =>
      `ID: ${e.id}\nNombre: ${e.nombre}\nCuándo usarlo: ${e.descripcion}`,
  )
  .join("\n\n");

// Recupero el texto de las noticias y el edicion_id del Code de noticias.
const datosNoticias = $('ConsolidarNoticias').first().json;

return [
  {
    json: {
      edicion_id: datosNoticias.edicion_id,
      texto_noticias: datosNoticias.texto_noticias,
      menu_estilos: menuEstilos,
      estilos: estilos,
    },
  },
];

// Parsea la elección de Groq, busca la imagen del estilo elegido,
// y arma el paquete para la razonadora multimodal (Gemini).
const respuestaGroq = $input.first().json.choices[0].message.content;

let elegido;
try {
  elegido = JSON.parse(respuestaGroq);
} catch (e) {
  throw new Error("No se pudo parsear la elección de Groq: " + respuestaGroq);
}

const estiloId = elegido.estilo_id;

// Recupero el paquete con noticias + estilos del segundo Code.
const datos = $('Code in JavaScript').first().json;

// Busco el estilo elegido entre los disponibles.
const estiloElegido = datos.estilos.find((e) => e.id === estiloId);

if (!estiloElegido) {
  throw new Error("El estilo elegido no se encontró en el banco: " + estiloId);
}

return [
  {
    json: {
      edicion_id: datos.edicion_id,
      texto_noticias: datos.texto_noticias,
      estilo_id: estiloId,
      estilo_nombre: estiloElegido.nombre,
      estilo_imagen_url: estiloElegido.imagen_url,
      estilo_notas: estiloElegido.notas_estilo || "",
    },
  },
];

// Extrae el prompt limpio que generó la razonadora (Gemini),
// y arrastra el edicion_id para los pasos siguientes.
const item = $input.first().json;

// El prompt viene en content.parts[0].text
let prompt = item.content?.parts?.[0]?.text || "";

// Limpieza menor: sacar asteriscos de markdown y espacios sobrantes.
prompt = prompt.replace(/\*\*/g, "").trim();

if (!prompt) {
  throw new Error("La razonadora no devolvió un prompt.");
}

// Recupero el edicion_id del Code anterior (Code in JavaScript1).
const datos = $('Code in JavaScript1').first().json;

return [
  {
    json: {
      edicion_id: datos.edicion_id,
      prompt_portada: prompt,
    },
  },
];

// Arma la URL pública de la portada subida y reúne los datos para guardar.
const key = $input.first().json.Key; // ej: "portadas/eeeeeeee..._...jpg"

const urlPublica =
  "https://eapsfpjahdbjypvxvutt.supabase.co/storage/v1/object/public/" + key;

// Recupero edicion_id y prompt del Code que limpió el prompt.
const datosPrompt = $('Code in JavaScript2').first().json;

// Recupero el estilo_id del Code que eligió el estilo.
const datosEstilo = $('Code in JavaScript1').first().json;

return [
  {
    json: {
      edicion_id: datosPrompt.edicion_id,
      imagen_url: urlPublica,
      prompt: datosPrompt.prompt_portada,
      estilo_id: datosEstilo.estilo_id,
    },
  },
];

